def history_nodes(n,bvid,path='$'):
    found=[]
    if isinstance(n,dict):
        if n.get('bvid')==bvid or n.get('game_slug','').find(bvid)>=0:
            found.append({'pointer':path,'value':{k:v for k,v in n.items() if k in ['bvid','summary','changes','patches','decisions','reason','conclusion','phases','evidence']}})
        else:
            for k,v in n.items():
                if k==bvid: found.append({'pointer':path+'/'+k,'value':v})
                else: found.extend(history_nodes(v,bvid,path+'/'+str(k)))
    elif isinstance(n,list):
        for i,v in enumerate(n):found.extend(history_nodes(v,bvid,path+'/'+str(i)))
    return found

